mapper.select:
select list.* from ( 
where u.del_flag = '0'

and ic.accept_node = #{platformCode}


	AND (u.user_name like CONCAT(CONCAT('%', #{searchKeyword}),'%')
	or u.phonenumber like CONCAT(CONCAT('%', #{searchKeyword}),'%')
	or u.nick_name like CONCAT(CONCAT('%', #{searchKeyword}),'%'))


	AND u.USER_TYPE = #{userType}


	AND u.user_name like CONCAT(CONCAT('%', #{userName}),'%')


	AND u.user_name = #{exactUserName}


	AND u.nick_name like CONCAT(CONCAT('%', #{nickName}),'%')


	AND u.status = #{status}


	AND u.phonenumber like CONCAT(CONCAT('%', #{phonenumber}),'%')


	AND u.create_time >= STR_TO_DATE(CONCAT(#{beginTime}, ' 00:00:00'),'%Y-%m-%d %H:%i:%s %T')


	AND u.create_time <= STR_TO_DATE(CONCAT(#{endTime}, ' 23:59:59'),'%Y-%m-%d %H:%i:%s %T')


	AND (u.dept_id = #{deptId} OR d.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE INSTR(ANCESTORS, #{deptId})>0 ) )


	AND (
	u.dept_id IN

		#{deptId}

	OR d.dept_id IN

		#{deptId}

	OR u.dept_id IN (
	SELECT t.dept_id
	FROM sys_dept t
	WHERE

		INSTR(t.ANCESTORS, #{deptId}) > 0

	)
	)


	AND u.tenant_id = #{tenantId}


	AND (
	u.tenant_id like CONCAT(CONCAT('%', #{tenantIdOrName}),'%')
	or
	st.tenant_name like CONCAT(CONCAT('%', #{tenantIdOrName}),'%')
	)


	AND u.tower_user_source = #{towerUserSource}



	AND u.user_id in (select e.user_id from sys_user_role e where e.role_id = #{roleIdquery})


${dataScope}
ORDER BY u.create_time DESC ) list


where u.del_flag = '0'
and ic.accept_node = #{platformCode}
AND u.user_name in

	#{id}


where u.del_flag = '0' AND u.user_name = #{userName}
${dataScope}
limit 1

select * from sys_user u
where u.del_flag = '0' AND u.user_id in

	#{id}


where u.del_flag = '0' AND u.user_id = #{userId}

and ic.accept_node = #{platformCode}


	and d.INDUSTRY_CODE=#{industryCode}

${dataScope}
limit 1

select DISTINCT d.parent_id, d.dept_name, d.parent_name, d.dept_level, d.order_num, d.leader, d.status as dept_status, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN d.dept_id ELSE d.parent_id END province_dept, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN NULL ELSE d.dept_id END city_dept from sys_dept d where d.del_flag = '0'
AND d.dept_id IN
#{labelIdItem}
${dataScope}

mapper.update:
update sys_user
USER_NAME = #{userName}, dept_id = #{deptId}, nick_name = #{nickName}, user_type = #{userType}, email = #{email}, phonenumber = #{phonenumber}, tel_phone = #{telPhone}, sex = #{sex}, avatar = #{avatar}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, enterprise_id = #{enterpriseId}, tenant_id = #{tenantId}, tenant_id = null, is_tenant_admin = #{isTenantAdmin}, user_source = #{userSource}, grade=#{grade}, emp_no=#{empNo}, sort_no=#{sortNo}, source=#{source}, province_id=#{provinceId}, city_id=#{cityId}, city_id=null, pwd_update_time = null,password=#{password}, validity_period_state = #{validityPeriodState},account_validity_period = #{accountValidityPeriod}, white_ip_flag = #{whiteIpFlag}, update_time = #{updateTime}
where user_id = #{userId}

update bm_gridkeeper
keeper_name = #{keeperName}, keeper_phone_number = #{keeperPhoneNumber}, keeper_email = #{keeperEmail}, keeper_gender = #{keeperGender}, update_time = NOW()
where staff_id = #{staffId}

 		update sys_user set status = #{status}

			, validity_period_state = #{validityPeriodState}, account_validity_period = #{accountValidityPeriod}


 		, password = #{password},pwd_update_time = null

 		where user_id = #{userId}

 		update sys_user set login_fail_num =

			login_fail_num+1
			#{num}

 		where user_name = #{userName}

update sys_user
dept_id = #{deptId}, nick_name = #{nickName}, user_type = #{userType}, email = #{email}, phonenumber = #{phonenumber}, tel_phone = #{telPhone}, sex = #{sex}, avatar = #{avatar}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, enterprise_id = #{enterpriseId}, user_source = #{userSource}, tenant_id = #{tenantId}, tenant_id = null, grade=#{grade}, emp_no=#{empNo}, sort_no=#{sortNo}, source=#{source}, province_id=#{provinceId}, city_id=#{cityId}, PASSWORD=#{password}, update_time = #{updateTime}
where user_name = #{userName}

mapper.select:
SELECT i.device_code AS deviceCode, i.device_name AS deviceName, u.tenant_id AS tenantId, i.province_id AS provinceId, a1.area_name AS provinceName , i.city_id AS cityId, a2.area_name AS cityName, i.county_id AS countyId, a3.area_name AS countyName FROM vm_device_info_t i LEFT JOIN vm_organ_device_rel_t t ON t.device_code = i.device_code LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT u_inner.user_id, u_inner.tenant_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u_inner.dept_id, ',', n), ',', -1) AS split_dept_id FROM sys_user u_inner JOIN cte ON cte.n <= ( LENGTH(u_inner.dept_id) - LENGTH(REPLACE(u_inner.dept_id, ',', '')) + 1 ) ) u_split ON t.dept_id = u_split.split_dept_id LEFT JOIN sys_user u ON u_split.user_id = u.user_id AND u.tenant_id = t.tenant_id LEFT JOIN sys_area a1 ON a1.AREA_CODE = i.province_id LEFT JOIN sys_area a2 ON a2.AREA_CODE = i.city_id LEFT JOIN sys_area a3 ON a3.AREA_CODE = i.county_id AND u.tenant_id = t.tenant_id WHERE u.user_id = #{userId} AND i.province_id IS NOT NULL AND u.del_flag = '0' AND t.delete_flag = '0'
and u.dept_id in
#{item}

SELECT DISTINCT i.device_code AS deviceCode FROM vm_device_info_t i LEFT JOIN vm_organ_device_rel_t t ON t.device_code = i.device_code LEFT JOIN sys_user u ON u.dept_id = t.dept_id LEFT JOIN sys_area a1 ON a1.AREA_CODE = i.province_id LEFT JOIN sys_area a2 ON a2.AREA_CODE = i.city_id LEFT JOIN sys_area a3 ON a3.AREA_CODE = i.county_id AND u.tenant_id = t.tenant_id WHERE u.user_id = #{userId} AND i.province_id IS NOT NULL AND u.del_flag = '0' AND t.delete_flag = '0'
and u.dept_id in
#{item}

select * from sys_user u
where u.del_flag = '0' AND u.user_name in

	#{name}

SELECT DISTINCT
a.PROVINCE_CODE AS areaCode, b.AREA_NAME AS areaName, b.AREA_LEVEL AS areaLevel, b.AREA_PARENT_CODE AS areaParentCode, b.LONGITUDE AS longitude, b.LATITUDE AS latitude
a.CITY_CODE AS areaCode, c.AREA_NAME AS areaName, c.AREA_LEVEL AS areaLevel, c.AREA_PARENT_CODE AS areaParentCode, c.LONGITUDE AS longitude, c.LATITUDE AS latitude
a.COUNTY_CODE AS areaCode, d.AREA_NAME AS areaName, d.AREA_LEVEL AS areaLevel, d.AREA_PARENT_CODE AS areaParentCode, d.LONGITUDE AS longitude, d.LATITUDE AS latitude
a.STREET_AREA_CODE AS areaCode, e.AREA_NAME AS areaName, e.AREA_LEVEL AS areaLevel, e.AREA_PARENT_CODE AS areaParentCode, e.LONGITUDE AS longitude, e.LATITUDE AS latitude
FROM sys_dept_street_rel a LEFT JOIN sys_area b ON a.PROVINCE_CODE = b.AREA_CODE LEFT JOIN sys_area c ON a.city_code = c.AREA_CODE LEFT JOIN sys_area d ON a.county_code = d.AREA_CODE LEFT JOIN sys_area e ON a.STREET_AREA_CODE = e.AREA_CODE WHERE 1 = 1
and b.AREA_PARENT_CODE = #{areaParentCode}
and c.AREA_PARENT_CODE = #{areaParentCode}
and d.AREA_PARENT_CODE = #{areaParentCode}
and e.AREA_PARENT_CODE = #{areaParentCode}
${dataScope}
